const $=s=>document.querySelector(s);
// Photo enlargement never changes the partial-intake selection.
Object.assign(words.zh,{exit:'回主页',partialC:'选出已吃下的药盒，放到下面',descC:'先看本次药盒总览。部分服用时，点药盒下方按钮移入“已吃下”区域；可移回纠正。'});
Object.assign(words.en,{exit:'Home',partialC:'Move the medicines you have taken below',descC:'See a photo overview. For partial intake, use the button beneath each box to move it into the taken group, or move it back.'});
const variantParam=new URLSearchParams(location.search).get('variant');
const s={variant:['A','B','C'].includes(variantParam)?variantParam:'A',lang:'zh',scale:100,scene:'multi',screen:'home',count:3,due:true,outcomes:['due','due','due'],sync:'pending',index:0,draft:{},focusBox:0,returnScreen:'alarm',interrupted:false,snapshot:null,lastReported:[],details:false,photoURLs:['assets/box-a.jpg','assets/box-b.jpg','assets/box-c.jpg']};
let retryTimer;
const t=()=>words[s.lang];
const esc=x=>String(x).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
const meds=[{label:'AGEN 5',n:1},{label:'ALDACTONE',n:1},{label:'SINTROM',n:2}];
const active=()=>Array.from({length:s.count},(_,i)=>i).filter(i=>s.outcomes[i]!=='taken');
const selected=()=>Object.keys(s.draft).map(Number).filter(i=>s.draft[i]==='taken'&&s.outcomes[i]!=='taken');
const btn=(label,act,cls='',extra='')=>`<button class="btn ${cls}" data-act="${act}" ${extra}>${label}</button>`;
const link=(label,act,extra='')=>`<button class="link" data-act="${act}" ${extra}>${label}</button>`;
function photo(i,zoom=true){const a=t();const img=`<img class="photo" src="${esc(s.photoURLs[i])}" alt="${a.box} ${i+1} · ${meds[i].label}" loading="eager">`;return zoom?`<button class="photo-button" data-act="zoom" data-id="${i}" aria-label="${a.zoom} · ${a.box} ${i+1}">${img}<span class="enlarge">${a.zoom}</span></button>`:img}
function medText(i){const a=t();return `<div class="med-head"><p class="dose">${a.take(meds[i].n)}</p><span class="badge">${a.box} ${i+1}</span></div>${s.photoURLs[i].startsWith('blob:')?'':`<p class="med-name">${meds[i].label}</p>`}`}
function status(i){const a=t();const value={taken:a.done,missing:a.notFound,unsure:a.uncertain,later:a.later,due:a.unknown}[s.outcomes[i]];return s.outcomes[i]==='due'?'':`<p class="${s.outcomes[i]==='taken'?'outcome':'problem'}">${s.outcomes[i]==='taken'?'✓':'!'} ${value}</p>`}
function med(i,select=false){const a=t();return `<article class="medicine">${photo(i)}${medText(i)}${status(i)}${select?`<label class="check"><input type="checkbox" data-check="${i}" ${s.draft[i]==='taken'?'checked':''}><span>${a.check}</span></label>${link(a.unsure,'uncertain',`data-id="${i}"`)}`:''}</article>`}
function pager(ids){const a=t();const k=Math.min(s.index,ids.length-1);return `<div class="pager">${btn(a.prev,'box-prev','',k===0?'disabled':'')}<span>${a.position(k+1,ids.length)}</span>${btn(a.next,'box-next','',k===ids.length-1?'disabled':'')}</div>`}
function variantA(ids,partial){return ids.map(i=>med(i,partial)).join('')}
function variantB(ids,partial){const a=t();const i=ids[Math.min(s.index,ids.length-1)];return `<section class="carousel">${pager(ids)}${photo(i)}${medText(i)}${status(i)}${partial?`<div class="answer">${btn(a.yes,'answer',s.draft[i]==='taken'?'chosen':'',`data-id="${i}" data-value="taken" aria-pressed="${s.draft[i]==='taken'}"`)}${btn(a.no,'answer',s.draft[i]==='no'?'chosen':'',`data-id="${i}" data-value="no" aria-pressed="${s.draft[i]==='no'}"`)}${link(a.unsure,'uncertain',`data-id="${i}"`)}</div>`:''}</section>`}
function tile(i,mode){const a=t();const picked=s.draft[i]==='taken';return `<article class="tile ${picked?'selected':''}">${photo(i)}${medText(i)}${status(i)}${mode?btn(picked?a.remove:a.move,'move','',`data-id="${i}" aria-pressed="${picked}"`):''}${mode?link(a.unsure,'uncertain',`data-id="${i}"`):''}</article>`}
function variantC(ids,partial){const a=t();return partial?`<section class="tray"><h2>${a.unselected}</h2><div class="overview">${ids.filter(i=>s.draft[i]!=='taken').map(i=>tile(i,true)).join('')||`<p>${a.none}</p>`}</div></section><section class="tray done"><h2>✓ ${a.selected} · ${selected().length}</h2><div class="overview">${ids.filter(i=>s.draft[i]==='taken').map(i=>tile(i,true)).join('')||`<p>${a.none}</p>`}</div></section>`:`<h2>${a.overview}</h2><div class="overview">${ids.map(i=>tile(i,false)).join('')}</div>`}
function photos(ids,partial=false){if(ids.length===1)return med(ids[0],partial);return s.variant==='A'?variantA(ids,partial):s.variant==='B'?variantB(ids,partial):variantC(ids,partial)}
function syncInfo(){const a=t();return `<div class="notice ${s.sync==='attention'?'warning':''}"><strong>${s.sync==='synced'?a.syncSynced:s.sync==='attention'?a.syncAttention:a.syncPending}</strong>${s.details?`<p>${s.sync==='attention'?a.syncAttentionDetail:s.sync==='pending'?a.syncPendingDetail:''}</p>${s.sync==='attention'?btn(a.retry,'retry'):''}`:link(a.syncDetails,'sync-details')}</div>`}
function home(){const a=t(),left=active().length,recorded=s.outcomes.slice(0,s.count).includes('taken'),snoozed=left>0&&active().every(i=>s.outcomes[i]==='later');return `<section class="home"><div class="hero-symbol" aria-hidden="true">${!s.due?'○':left===0?'✓':snoozed?'◷':'◉'}</div><h1>${!s.due?a.ready:left===0?a.recorded:snoozed?a.snoozed:s.interrupted||recorded?a.unfinished:a.dueHome}</h1><p class="quiet">${!s.due?a.readyBody:left===0?a.doneBody:snoozed?a.snoozeBody:a.time}</p>${s.due&&left>0?btn(s.interrupted||recorded?a.resume:a.open,'open','primary'):''}${recorded?syncInfo():''}${s.snapshot?link(a.correction,'correct'):''}</section>`}
function alarm(){const a=t(),ids=active();if(!ids.length)return result();const issues=ids.some(i=>['missing','unsure'].includes(s.outcomes[i]));return `<p class="eyebrow">${a.time}</p><h1>${a.alarm}</h1><p>${a.gather}</p>${photos(ids)}${issues?`<div class="notice warning">${a.warnMissing}</div>`:''}<div class="actions">${issues?btn(a.partialEntry,'partial','primary'):btn(ids.length===1?a.oneTaken:a.allTaken,'all','primary')}${btn(a.later,'later')}${link(a.exception,'problems')}</div>`}
function partial(){const a=t(),ids=active();return `<h1>${s.variant==='A'?a.partialA:s.variant==='B'?a.partialB:a.partialC}</h1><p>${a.partialLead}</p>${photos(ids,true)}<div class="actions">${btn(selected().length?a.save(selected().length):a.saveEmpty,'review','primary',selected().length?'':'disabled')}${link(a.back,'alarm')}</div>`}
function problems(){const a=t();return `<h1>${a.problemTitle}</h1><p>${a.problemBody}</p><div class="actions">${btn(a.missing,'missing-select')}${btn(s.count===1?a.singlePartial:a.partialEntry,s.count===1?'single-unsure':'partial')}${btn(a.later,'later')}${link(a.continue,'alarm')}</div>`}
function chooseMissing(){const a=t();return `<h1>${a.whichMissing}</h1>${active().map(i=>`<article class="medicine">${photo(i)}${medText(i)}${btn(a.missing,'missing','',`data-id="${i}"`)}</article>`).join('')}`}
function missing(){const a=t(),i=s.focusBox;return `<h1>${a.missingTitle}</h1>${photo(i)}<p class="badge">${a.box} ${i+1}</p><p>${a.missingBody}</p><div class="actions">${btn(a.findLater,'defer-missing','primary')}${btn(a.contact,'contact-missing')}${btn(a.partialEntry,'partial')}${link(a.continue,'alarm')}</div>`}
function uncertain(){const a=t();return `<h1>${a.uncertainTitle}</h1>${photo(s.focusBox)}<p>${a.uncertainBody}</p><div class="actions">${btn(a.contactPerson,'contact-person','primary')}${btn(a.partialEntry,'partial')}${link(a.continue,'alarm')}</div>`}
function review(){const a=t();return `<h1>${a.reviewTitle}</h1><p>${a.reviewBody}</p>${selected().map(i=>`<article class="medicine">${photo(i)}${medText(i)}</article>`).join('')}<div class="actions">${btn(a.save(selected().length),'save','primary',selected().length?'':'disabled')}${btn(a.editSelection,'partial-back')}</div>`}
function result(){const a=t(),left=active().length;return `<div class="hero-symbol" aria-hidden="true">✓</div><h1>${a.recordedN(s.lastReported.length)}</h1>${left?`<div class="notice warning"><h2>${a.remainingN(left)}</h2><p>${a.remainingBody}</p></div>`:`<p>${a.doneBody}</p>`}${syncInfo()}<div class="actions">${left?btn(a.remaining,'resume','primary'):''}${btn(a.toHome,'home')}${s.snapshot?link(a.correction,'correct'):''}</div>`}
function resume(){const a=t();return `<h1>${a.resumeTitle}</h1><p>${a.resumeBody}</p>${s.outcomes.includes('taken')?`<div class="notice">${a.resumeTaken}</div>`:''}<div class="actions">${btn(a.allResume,'all','primary')}${btn(s.count===1?a.singlePartial:a.partialEntry,s.count===1?'single-unsure':'partial')}${btn(a.notYet,'alarm')}${link(a.missing,'missing-select')}</div>`}
function render(){const a=t();document.documentElement.lang=s.lang==='zh'?'zh-CN':'en';document.documentElement.style.setProperty('--scale',s.scale/100);document.body.classList.toggle('scale200',s.scale===200);$('#watermark').textContent=a.prototype;$('#variant-label').textContent=a['version'+s.variant];$('#controls-title').textContent=a.controls;
let content='';switch(s.screen){case'home':content=home();break;case'alarm':content=alarm();break;case'partial':content=partial();break;case'problems':content=problems();break;case'missing-select':content=chooseMissing();break;case'missing':content=missing();break;case'uncertain':content=uncertain();break;case'review':content=review();break;case'result':content=result();break;case'resume':content=resume();break;case'snoozed':content=`<div class="hero-symbol">◷</div><h1>${a.snoozed}</h1><p>${a.snoozeBody}</p>${btn(a.toHome,'home','primary')}`;break;case'contact':content=`<h1>${a.contactDone}</h1><p>${a.contactBody}</p>${btn(a.continue,'alarm','primary')}`;break;case'contact-person':content=`<h1>${a.contactPerson}</h1><p>${a.contactPersonBody}</p>${btn(a.continue,'alarm','primary')}`;break;case'zoom':content=`<h1>${a.box} ${s.focusBox+1}</h1><img class="fullphoto" src="${esc(s.photoURLs[s.focusBox])}" alt="${a.box} ${s.focusBox+1} · ${meds[s.focusBox].label}">${medText(s.focusBox)}${btn(a.back,'zoom-back','primary')}`;break;}
$('#app').innerHTML=`<header><div class="brand">${a.brand}</div>${s.screen!=='home'?`<div class="topline">${['alarm','resume'].includes(s.screen)?'':link(a.back,'back')}${link(a.exit,'exit')}</div>`:''}</header>${content}`;
$('#control-body').innerHTML=`<label>${a.language}</label><div class="row"><button data-lang="zh" aria-pressed="${s.lang==='zh'}">简体中文</button><button data-lang="en" aria-pressed="${s.lang==='en'}">English</button></div><label>${a.font}</label><div class="row"><button data-scale="100" aria-pressed="${s.scale===100}">100%</button><button data-scale="200" aria-pressed="${s.scale===200}">200%</button></div><label for="scenario">${a.scenario}</label><select id="scenario"><option value="idle" ${s.scene==='idle'?'selected':''}>${a.idle}</option><option value="single" ${s.scene==='single'?'selected':''}>${a.single}</option><option value="multi" ${s.scene==='multi'?'selected':''}>${a.multi}</option></select><label>${a.sync}</label><div class="row">${['pending','synced','attention'].map(x=>`<button data-sync="${x}" aria-pressed="${s.sync===x}">${a[x]}</button>`).join('')}</div><p><button data-act="fire">${a.fire}</button></p><label>${a.photos}</label>${meds.map((m,i)=>`<label for="upload-${i}">${a.box} ${i+1}</label><input id="upload-${i}" type="file" accept="image/*" data-upload="${i}">`).join('')}<p>${a.photoNote}</p><a href="README.md" target="_blank">${a.photoSource}</a>`;
$('#bench-description').innerHTML=`<p><strong>${a['version'+s.variant]}</strong></p><p>${a['desc'+s.variant]}</p><p>${a.learn}</p>`;
$('#readout').textContent=JSON.stringify({variant:s.variant,scene:s.scene,screen:s.screen,language:s.lang,fontScale:s.scale,plannedTime:'18:00',snoozeTarget:s.outcomes.includes('later')?'18:10':null,interrupted:s.interrupted,doseOutcomes:s.outcomes.slice(0,s.count),selectionDraft:s.draft,synchronization:s.sync,lastReported:s.lastReported},null,2);
}
function page(name){s.screen=name;render();window.scrollTo({top:0,behavior:'instant'})}
function reset(scene){clearTimeout(retryTimer);s.scene=scene;s.count=scene==='single'?1:3;s.due=scene!=='idle';s.outcomes=['due','due','due'];s.screen=scene==='idle'?'home':'alarm';s.index=0;s.draft={};s.interrupted=false;s.snapshot=null;s.lastReported=[];s.details=false;s.sync='pending';render();window.scrollTo(0,0)}
function commit(ids){if(!ids.length)return;s.snapshot={outcomes:[...s.outcomes],lastReported:[...s.lastReported]};ids.forEach(i=>s.outcomes[i]='taken');s.lastReported=ids;s.sync='pending';s.draft={};s.details=false;s.interrupted=false;page('result')}
function variant(offset){const all=['A','B','C'];s.variant=all[(all.indexOf(s.variant)+offset+3)%3];const u=new URL(location.href);u.searchParams.set('variant',s.variant);if(s.variant==='C'){location.assign(u);return}history.replaceState(null,'',u);render()}
document.addEventListener('change',e=>{if(e.target.id==='scenario')return reset(e.target.value);if(e.target.dataset.check!==undefined){s.draft[e.target.dataset.check]=e.target.checked?'taken':'no';const y=window.scrollY;render();window.scrollTo(0,y)}if(e.target.dataset.upload!==undefined&&e.target.files[0]){s.photoURLs[Number(e.target.dataset.upload)]=URL.createObjectURL(e.target.files[0]);render()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.lang){s.lang=b.dataset.lang;render();return}if(b.dataset.scale){s.scale=Number(b.dataset.scale);render();return}if(b.dataset.sync){s.sync=b.dataset.sync;render();return}const act=b.dataset.act,id=Number(b.dataset.id);switch(act){case'variant-prev':variant(-1);break;case'variant-next':variant(1);break;case'open':s.index=0;page(s.interrupted||s.outcomes.includes('taken')||s.outcomes.includes('later')?'resume':'alarm');break;case'home':page('home');break;case'exit':s.interrupted=active().length>0;page('home');break;case'back':if(s.screen==='zoom')page(s.returnScreen);else if(s.screen==='review')page('partial');else if(s.screen==='alarm'||s.screen==='resume'){s.interrupted=true;page('home')}else page('alarm');break;case'alarm':s.index=0;page('alarm');break;case'partial':s.index=0;page('partial');break;case'partial-back':page('partial');break;case'problems':page('problems');break;case'missing-select':page('missing-select');break;case'missing':s.focusBox=id;s.outcomes[id]='missing';delete s.draft[id];page('missing');break;case'defer-missing':s.outcomes[s.focusBox]='later';page('alarm');break;case'contact-missing':page('contact');break;case'contact-person':page('contact-person');break;case'uncertain':s.focusBox=id;s.outcomes[id]='unsure';delete s.draft[id];page('uncertain');break;case'single-unsure':s.focusBox=active()[0];s.outcomes[s.focusBox]='unsure';page('uncertain');break;case'box-prev':s.index=Math.max(0,s.index-1);page(s.screen);break;case'box-next':s.index=Math.min(active().length-1,s.index+1);page(s.screen);break;case'answer':s.draft[id]=b.dataset.value;render();break;case'move':s.draft[id]=s.draft[id]==='taken'?'no':'taken';render();break;case'review':if(selected().length)page('review');break;case'save':commit(selected());break;case'all':commit(active());break;case'later':active().forEach(i=>{if(s.outcomes[i]!=='unsure')s.outcomes[i]='later'});page('snoozed');break;case'resume':page('resume');break;case'correct':if(s.snapshot){s.outcomes=[...s.snapshot.outcomes];s.lastReported=[...s.snapshot.lastReported];s.snapshot=null;s.draft={};s.index=0;page('partial')}break;case'zoom':s.focusBox=id;s.returnScreen=s.screen;page('zoom');break;case'zoom-back':page(s.returnScreen);break;case'sync-details':s.details=true;render();break;case'retry':s.sync='pending';render();clearTimeout(retryTimer);retryTimer=setTimeout(()=>{s.sync='synced';render()},700);break;case'fire':if(s.due&&active().length){s.interrupted=true;page('resume')}break;}});
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||e.target.isContentEditable)return;if(e.key==='ArrowLeft'){e.preventDefault();variant(-1)}if(e.key==='ArrowRight'){e.preventDefault();variant(1)}});
render();
